{
"html": "<div data-ui-unit="E4a" class="e4a-card">
    <div class="e4a-header">
        <div class="e4a-avatar-group">
            <img src="assets/reference/avatar-1.png" alt="김서연 프로필 사진" class="e4a-avatar">
            <div class="e4a-info">
                <h3 class="e4a-name">김서연</h3>
                <div class="e4a-meta">
                    <img src="assets/reference/bookmark-check.svg" alt="현직 표시" class="e4a-icon-bookmark">
                    <span class="e4a-badge">현직</span>
                    <span class="e4a-divider"></span>
                    <span class="e4a-role">스타트업 A</span>
                </div>
            </div>
        </div>
        <button type="button" disabled aria-label="김서연 찜한 상태 예시" class="e4a-favorite">
            <img src="assets/reference/heart.svg" alt="찜하기" class="e4a-icon-heart">
        </button>
    </div>
    <div class="e4a-body">
        <label for="e4a-desc">소개글</label>
        <textarea id="e4a-desc" rows="3" disabled>실무 중심의 멘토링을 통해 성장하는 개발자를 돕고 있습니다. 스타트업 환경에서의 프로덕트 개발 경험을 공유합니다.</textarea>
    </div>
</div>",
"css": ".e4a-card {
    background: var(--surface, #fff);
    border-radius: 14px;
    padding: 16px;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.e4a-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    min-width: 0;
    position: relative;
}

.e4a-avatar-group {
    display: flex;
    align-items: center;
    min-width: 0;
    flex: 1;
}

.e4a-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    object-fit: cover;
    flex-shrink: 0;
}

.e4a-info {
    display: flex;
    flex-direction: column;
    margin-left: 8px;
    min-width: 0;
}

.e4a-name {
    font-family: "Noto Sans KR", sans-serif;
    font-size: 18px;
    line-height: 24px;
    font-weight: 700;
    color: var(--ink, #283548);
    margin: 0;
    padding: 0;
    white-space: nowrap;
}

.e4a-meta {
    display: flex;
    align-items: center;
    margin-top: 2px;
    font-size: 14px;
    line-height: 1.5;
    color: var(--muted, #566273);
    min-width: 0;
}

.e4a-icon-bookmark {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
    margin-right: 4px;
}

.e4a-badge {
    background-color: #e6f0ff;
    color: var(--blue, #365bcc);
    font-size: 12px;
    line-height: 20px;
    padding: 1px 6px;
    border-radius: 6px;
    white-space: nowrap;
}

.e4a-divider {
    width: 1px;
    height: 14px;
    background-color: #dce1e8;
    margin: 0 8px;
    display: inline-block;
    vertical-align: middle;
}

.e4a-role {
    white-space: nowrap;
}

.e4a-favorite {
    background: transparent;
    border: none;
    padding: 0;
    margin-left: 8px;
    cursor: pointer;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-top: -2px;
}

.e4a-icon-heart {
    width: 24px;
    height: 24px;
    fill: var(--red, #e85260);
}

.e4a-body {
    margin-top: 16px;
}

.e4a-body label {
    display: block;
    font-size: 14px;
    color: var(--muted, #566273);
    margin-bottom: 6px;
}

#e4a-desc {
    width: 100%;
    resize: none;
    border: 1px solid transparent;
    background: transparent;
    color: var(--ink, #283548);
    padding: 0;
    font-family: "Noto Sans KR", sans-serif;
    font-size: 14px;
    line-height: 1.57;
    margin: 0;
}

@media (prefers-reduced-motion: reduce) {
    .e4a-card, .e4a-icon-heart {
        transition: none !important;
        animation: none !important;
    }
}"
}
